// Custom Cloudflare Worker entry: OpenNext's fetch handler for the Next.js app, plus a cron handler
// that runs the Telegram watch checks every few minutes (schedule in wrangler.jsonc "triggers").
// .open-next/worker.js is generated by `opennextjs-cloudflare build`.
import handler from "./.open-next/worker.js";

const worker = {
  fetch: handler.fetch,

  async scheduled(_event, env, ctx) {
    const request = new Request("https://loxley.internal/api/alerts/tick", {
      method: "POST",
      headers: { "x-loxley-tick": env.TELEGRAM_WEBHOOK_SECRET ?? "" },
    });
    ctx.waitUntil(handler.fetch(request, env, ctx));
  },
};

export default worker;
